"""
Real Vector Database using live Gemini Embeddings and Vector Cosine Similarity.
Indexes actual knowledge base articles and queries them via 3072-dimensional vector math.
"""

from typing import List, Dict, Any, Optional
from simulator.real_gemini_service import RealGeminiService, cosine_similarity
from simulator.fixtures import KNOWLEDGE_BASE_ARTICLES


class RealGeminiVectorStore:
    """Stores real vector embeddings generated by Google Gemini and queries by cosine similarity."""

    def __init__(self, gemini_service: RealGeminiService, articles: Optional[List[Dict[str, Any]]] = None):
        self.gemini = gemini_service
        self.articles = articles or KNOWLEDGE_BASE_ARTICLES
        self.indexed_docs: List[Dict[str, Any]] = []

    def build_index(self):
        """Generates real 3072-dimensional embeddings for all knowledge base articles."""
        print(f"Building real vector index for {len(self.articles)} knowledge base articles via Gemini API...")
        for doc in self.articles:
            doc_text = f"{doc['title']}: {doc['text']}"
            embedding = self.gemini.get_embedding(doc_text)
            self.indexed_docs.append({
                "id": doc["id"],
                "title": doc["title"],
                "text": doc["text"],
                "category": doc["category"],
                "embedding": embedding
            })
        print("Vector index built successfully with live Gemini embeddings!")

    def query(self, query_text: str, top_k: int = 3) -> Dict[str, Any]:
        """Generates a real query embedding and computes cosine similarity against indexed documents."""
        query_vec = self.gemini.get_embedding(query_text)
        scored_matches = []

        for doc in self.indexed_docs:
            score = cosine_similarity(query_vec, doc["embedding"])
            scored_matches.append({
                "id": doc["id"],
                "title": doc["title"],
                "text": doc["text"],
                "category": doc["category"],
                "score": round(score, 4)
            })

        scored_matches.sort(key=lambda x: x["score"], reverse=True)
        top_matches = scored_matches[:top_k]
        highest_score = top_matches[0]["score"] if top_matches else 0.0

        return {
            "query": query_text,
            "matches": top_matches,
            "highest_score": highest_score
        }
